head.script:
///////// 2. 초기화 영역 /////////
            /**
             * @method
             * @name onpageload
             * @description 화면 진입점 — 서식권한ID 파라미터를 수신하고 시장구분 공통코드(LD_MKT_TP_CD)를 조회하며 페이지 리스트를 초기화(숨김)한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (body ev:onpageload 바인딩으로 자동 호출)
             */
            scwin.onpageload = function (e) {

                dma_search.set("formAuthId", $c.data.getParameter("authId"));

                // 시장구분코드
                const list = ["LD_MKT_TP_CD"];
                const params = {"cdEngNmList":list};

                // 시장구분 정보 조회
                $c.sbm.execute(sbm_ldMktTpCd, params);

                // 초기화
                pgl_list.hide();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name btn_search_onclick
             * @description [조회] 버튼 클릭 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_search_onclick(e);
             */
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name sbx_page_onchange
             * @description 한 페이지 건수 변경 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} info 선택 변경 정보 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbx_page_onchange(info);
             */
            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name pgl_list_onclick
             * @description 페이지 번호 클릭 — 해당 페이지의 목록을 조회한다(총건수 미조회).
             * @param {Number} index 클릭한 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.pgl_list_onclick(1);
             */
            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

            /**
             * @method
             * @name btn_save_onclick
             * @description [선택 서식 추가] 버튼 클릭 — 체크된 행의 서식권한ID·서식코드·서식버전을 수집해 등록(sbm_save)을 실행한다. 체크된 서식이 없으면 알림을 표시한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_save_onclick(e);
             */
            scwin.btn_save_onclick = function (e) {

                const formAuthIdList = [];
                for (let i=0; i < dlt_list.getRowCount(); i++) {
                    if (dlt_list.getCellData(i, "CHK") === "1") {
                        // 이미 등록된 ID 체크 수정 필요
                        const params = {};
                        params.formAuthId = dma_search.get("formAuthId");
                        params.formCd = dlt_list.getCellData(i, "formCd");
                        params.formVer = dlt_list.getCellData(i, "formVer");

                        formAuthIdList.push(params);
                    }
                }

                // 등록 처리
                if (formAuthIdList.length > 0) {
                    $c.sbm.execute(sbm_save, formAuthIdList);
                } else {
                    $c.win.alert("등록할 서식을 체크 해주세요.");
                }
            };

            /**
             * @method
             * @name ibx_formKorNm_onkeyup
             * @description 검색조건명 입력란 키 입력 — Enter 키 입력 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_formKorNm_onkeyup(e);
             */
            scwin.ibx_formKorNm_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name btn_close_onclick
             * @description [취소/닫기] 버튼 클릭 — 팝업을 닫는다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_close_onclick(e);
             */
            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_ldMktTpCd_submitdone
             * @description 시장구분 공통코드 조회(sbm_ldMktTpCd) 콜백 — 시장구분 셀렉트박스를 구성하고 목록을 최초 조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_ldMktTpCd ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_ldMktTpCd_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                    // 조회
                    scwin.fnSearch("Y", 1);
                } else {
                    $c.win.alert(result.message);
                }
            };

            /**
             * @method
             * @name sbm_list_submitdone
             * @description 목록 조회(sbm_list) 콜백 — 최초 조회 시에만 총건수를 표시하고, 데이터 유무에 따라 페이지 리스트를 표시/숨김한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_list ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }
                } else {
                    $c.win.alert(result.message); 
                }             
            };

            /**
             * @method
             * @name sbm_save_submitdone
             * @description 등록(sbm_save) 콜백 — 성공 시 완료 알림 후 refreshYn("Y") 을 담아 팝업을 닫고, 실패 시 오류 메시지를 알린다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_save ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    const params = {};
                    params.refreshYn = "Y";

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            /**
             * @method
             * @name fnSearch
             * @description 목록 조회 — 총건수 조회 여부·페이지 번호·한 페이지 건수를 dma_search 에 설정하고 목록(sbm_list)을 조회한다.
             * @param {String} totYn 총건수 조회 여부("Y"/"N")
             * @param {Number} index 조회할 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.fnSearch("Y", 1);
             */
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };
